mapper.select:
select distinct t_s_role.id as role_id, t_s_role.name as role_name, t_s_role.enable as role_enable, t_s_role.create_time as role_create_time, t_s_role.update_time as role_update_time, t_s_role.deleted as role_deleted, t_s_role.version as role_version, tsm.id as module_id, tsm.name as module_name, tsmn.id as menu_id, tsmn.name as menu_name, tsmn.url as menu_url, tsmn.parent_id as menu_parent_id, tsmn.module_id as menu_module_id, tss.id as scope_id, tss.name as scope_name, tss.menu_id as scope_menu_id, tso.id as operation_id, tso.name as operation_name, tso.code as operation_code, tso.scope_id as operation_scope_id from (select * from t_s_role where deleted = 0) as t_s_role left join (select * from t_r_power_role where deleted = 0) as trpr on t_s_role.id = trpr.role_id left join t_s_power tsp on tsp.id = trpr.power_id left join t_s_module tsm on tsp.id = tsm.id left join t_s_menu tsmn on tsp.id = tsmn.id left join t_s_scope tss on tsp.id = tss.id left join t_s_operation tso on tsp.id = tso.id
#{item}
#{item}
